const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometry and date windows
  const point = ee.Geometry.Point([-136.325766, 69.954148]);
  const region = point.buffer(1000); // 1km buffer for reduction
  const juneWindow = ee.DateRange('2012-06-11', '2012-06-17');
  const julyWindow = ee.DateRange('2012-07-02', '2012-07-08');

  // Function to mask clouds and shadows in Landsat 5
  function maskL5sr(image) {
    const qaMask = image.select('QA_PIXEL').bitwiseAnd(parseInt('1111', 2)).eq(0);
    const saturationMask = image.select('QA_RADSAT').eq(0);
    return image.updateMask(qaMask).updateMask(saturationMask);
  }

  // Function to calculate NDTI (Normalized Difference Turbidity Index)
  function addNDTI(image) {
    const ndti = image.normalizedDifference(['SR_B3', 'SR_B2']).rename('NDTI');
    return image.addBands(ndti);
  }

  // 2. Get Landsat 5 collections for both periods
  let juneCol = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(point)
    .filterDate(juneWindow)
    .map(maskL5sr)
    .map(addNDTI);
  let julyCol = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(point)
    .filterDate(julyWindow)
    .map(maskL5sr)
    .map(addNDTI);

  // Check collection sizes
  const juneSize = juneCol.size().getInfo();
  const julySize = julyCol.size().getInfo();
  console.log(`June 14 window images: ${juneSize}`);
  console.log(`July 5 window images: ${julySize}`);

  // 3. Handle empty collections - try wider date windows if needed
  if (juneSize === 0 || julySize === 0) {
    // Try widening the date window by ±7 days
    console.log('One collection empty, trying wider date window (±7 days)...');
    juneCol = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
      .filterBounds(point)
      .filterDate('2012-06-07', '2012-06-21')
      .map(maskL5sr)
      .map(addNDTI);
    julyCol = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
      .filterBounds(point)
      .filterDate('2012-06-28', '2012-07-12')
      .map(maskL5sr)
      .map(addNDTI);

    const juneSizeWide = juneCol.size().getInfo();
    const julySizeWide = julyCol.size().getInfo();
    console.log(`June wide window images: ${juneSizeWide}`);
    console.log(`July wide window images: ${julySizeWide}`);

    if (juneSizeWide === 0 || julySizeWide === 0) {
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 4. Create median composites and compute mean NDTI
  const juneImg = juneCol.median();
  const julyImg = julyCol.median();

  // Function to compute statistics
  function getStats(img, periodName) {
    const stats = img.select('NDTI').reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: region,
      scale: 1000,
      maxPixels: 1e9,
      bestEffort: true
    });
    const mean = stats.get('NDTI_mean');
    const count = stats.get('NDTI_count');
    return {mean: mean, count: count};
  }

  const juneStats = getStats(juneImg, 'June');
  const julyStats = getStats(julyImg, 'July');

  // 5. Check for valid pixels
  const juneCount = juneStats.count.getInfo();
  const julyCount = julyStats.count.getInfo();
  console.log(`June valid pixels: ${juneCount}`);
  console.log(`July valid pixels: ${julyCount}`);

  if (juneCount === 0 || julyCount === 0) {
    console.log('<answer>C2</answer>');
    return;
  }

  // 6. Get mean values and validate
  const juneMean = juneStats.mean.getInfo();
  const julyMean = julyStats.mean.getInfo();
  console.log(`June mean NDTI: ${juneMean !== null ? juneMean.toFixed(4) : 'null'}`);
  console.log(`July mean NDTI: ${julyMean !== null ? julyMean.toFixed(4) : 'null'}`);

  // Validate results
  if (juneMean === null || julyMean === null || 
      isNaN(juneMean) || isNaN(julyMean) ||
      juneMean < -1 || juneMean > 1 || 
      julyMean < -1 || julyMean > 1) {
    console.log('<answer>C3</answer>');
    return;
  }

  // 7. Compare and output answer
  if (julyMean > juneMean) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
